var fs    = require('fs');
var https = require('https');
var http  = require('http');
var LOG_FILE = '/home/node/.n8n/jobsearch-log.json';

// ── CONFIG ──────────────────────────────────────────────────────────────────
var CLAUDE_MODEL   = 'claude-sonnet-4-6';
var FALLBACK_MODEL = 'llama3.2';
// ────────────────────────────────────────────────────────────────────────────

var apiKey = '';
try {
  var cfg = JSON.parse(fs.readFileSync('/home/node/.n8n/ai-config.json', 'utf8'));
  apiKey = cfg.anthropic_api_key || '';
} catch(e) {}

var resume = '[Resume not found]';
try { resume = fs.readFileSync('/jobhunt/resume.md', 'utf8'); } catch(e) {}

function callClaude(systemPrompt, userMessage, maxTokens) {
  return new Promise(function(resolve, reject) {
    var body = JSON.stringify({
      model: CLAUDE_MODEL, max_tokens: maxTokens || 2000,
      system: systemPrompt,
      messages: [{ role: 'user', content: userMessage }]
    });
    var opts = {
      hostname: 'api.anthropic.com', port: 443, path: '/v1/messages', method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body, 'utf8'),
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01'
      }
    };
    var req = https.request(opts, function(res) {
      var chunks = [];
      res.on('data', function(d) { chunks.push(d.toString()); });
      res.on('end',  function() { resolve({ ok: res.statusCode === 200, status: res.statusCode, text: chunks.join('') }); });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

function getClaudeText(r) {
  try {
    var p = JSON.parse(r);
    if (p.content && p.content[0]) return p.content[0].text || '';
    if (p.error) return 'Claude error: ' + (p.error.message || JSON.stringify(p.error));
  } catch(e) {}
  return r;
}

function isClaudeError(text) {
  return typeof text === 'string' && text.indexOf('Claude error:') === 0;
}

function callOllama(systemPrompt, userMessage) {
  return new Promise(function(resolve, reject) {
    var body = JSON.stringify({
      model: FALLBACK_MODEL,
      messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }],
      stream: false
    });
    var opts = {
      hostname: 'host.docker.internal', port: 11434, path: '/api/chat', method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body, 'utf8') }
    };
    var req = http.request(opts, function(res) {
      var chunks = [];
      res.on('data', function(d) { chunks.push(d.toString()); });
      res.on('end',  function() {
        if (res.statusCode < 200 || res.statusCode >= 300) return reject(new Error('Ollama HTTP ' + res.statusCode));
        try {
          var p = JSON.parse(chunks.join(''));
          resolve((p.message && p.message.content) ? p.message.content : (p.response || ''));
        } catch(e) { reject(e); }
      });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function generate(systemPrompt, userMessage, maxTokens) {
  try {
    var r   = await callClaude(systemPrompt, userMessage, maxTokens);
    var txt = getClaudeText(r.text);
    if (r.ok && !isClaudeError(txt)) return { text: txt, model: 'claude:' + CLAUDE_MODEL };
  } catch(e) {}
  var fallback = await callOllama(systemPrompt, userMessage);
  return { text: fallback, model: 'ollama:' + FALLBACK_MODEL };
}

async function getDossier(company, jobId, jobTitle, linkedinUrl) {
  return new Promise(function(resolve) {
    var payload = JSON.stringify({ company: company, jobId: jobId || '', jobTitle: jobTitle || '', linkedinUrl: linkedinUrl || '' });
    var bodyLen = typeof Buffer !== 'undefined' ? Buffer.byteLength(payload, 'utf8') : payload.length;
    var opts = {
      hostname: 'localhost', port: 5678, path: '/webhook/company-dossier', method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': bodyLen }
    };
    var req = http.request(opts, function(res) {
      var chunks = [];
      res.on('data', function(d) { chunks.push(d.toString()); });
      res.on('end',  function() {
        try { resolve(JSON.parse(chunks.join('')).dossier || null); }
        catch(e) { resolve(null); }
      });
    });
    req.on('error', function() { resolve(null); });
    req.setTimeout(30000, function() { req.destroy(); resolve(null); });
    req.write(payload);
    req.end();
  });
}

function safe(str) {
  return (str || 'Unknown').replace(/[<>:"\/\\|?*]/g, '-').replace(/\s+/g, ' ').trim().slice(0, 50);
}

