      '\nStage: '    + (dossier.stage    || 'Unknown') +
      '\nHQ: '       + (dossier.hq       || 'Unknown') +
      '\nRemote policy: ' + (dossier.remote || 'unknown') +
      '\nCulture signals: ' + (dossier.cultureSignals || []).join(', ') +
      '\nRecent news: '    + (dossier.recentNews || []).slice(0, 3).join('; ') +
      '\nOverview: '       + (dossier.researchNotes || '');
  }
  var jd      = (job.description || '').slice(0, 3000);
  var res     = resume.slice(0, 4000);
  var company = safe(job.company);
  var title   = safe(job.title);
  var today   = new Date().toISOString().slice(0, 10);

  var g1 = await generate(
    'You are a career researcher. Provide concise, factual notes to help a job applicant understand a potential employer.',
    'Role: ' + job.title + '\nCompany: ' + job.company + '\nLocation: ' + (job.location || '') +
    '\n\nJob description excerpt:\n' + jd.slice(0, 1500) +
    dossierCtx +
    '\n\nWrite company research as markdown with exactly these three sections, in this order. Output only the sections and their content, no preamble or closing remarks.\n\n## Company Overview\n[What the company does, its industry position, business model, and scale.]\n\n## Culture and Team Signals\n[Signals about culture, team, and working style from the job listing and any dossier data.]\n\n## Strategic Importance of ' + job.title + ' Role\n[Why this specific role matters strategically at this company right now.]\n\nIncorporate dossier data where available; fall back to job description signals. Each section should be one focused paragraph.',
    700);

  var g2 = await generate(
    'You are an expert resume writer. Tailor resumes to specific job descriptions while maintaining complete factual accuracy. Match vocabulary and emphasize relevant experience.',
    'JOB: ' + job.title + ' at ' + job.company +
    '\n\nJOB DESCRIPTION:\n' + jd +
    dossierCtx +
    '\n\n---\n\nMY RESUME:\n' + res +
    '\n\n---\n\nRewrite my resume tailored for this role. Use the exact vocabulary from the job description. Where culture signals are available in the dossier, align framing accordingly. Lead with the most relevant experience. Preserve all facts - do not invent anything. Format as clean Markdown with clear sections.',
    3000);

  var g3 = await generate(
    'You are an expert cover letter writer. Create compelling, authentic letters. Professional but human tone. No buzzwords: no "synergy", "passionate", "leverage", "excited to join", "touch base".',
    'Role: ' + job.title + ' at ' + job.company + '\nLocation: ' + (job.location || '') +
    '\n\nJob description:\n' + jd.slice(0, 2000) +
    dossierCtx +
    '\n\nMy background:\n' + res.slice(0, 2500) +
    '\n\nFit analysis: ' + (job.fitReasoning || '') +
    '\nKey matches: ' + (job.fitMatches || []).join(', ') +
    '\n\nWrite a cover letter (3-4 paragraphs). Address "Dear Hiring Manager," unless a specific name appears in the listing. Open by connecting my specific background to this specific role. If dossier data is available, weave in a specific detail about the company (recent news, stage, culture) to show genuine research. Highlight 2-3 accomplishments that map to job requirements. Close with a confident, specific call to action.',
    1200);

  var folderName = company + ' - ' + title;
  var jobNote =
    '---\n' +
    'date: ' + today + '\n' +
    'title: ' + job.title + '\n' +
    'company: ' + job.company + '\n' +
    'type: "job posting"\n' +
    'source: ' + (job.source || 'auto-search') + '\n' +
    'match-score: ' + (job.fitScore || 0) + '\n' +
    'url: ' + (job.linkedinUrl || '') + '\n' +
    'active: true\n' +
    'application: false\n' +
    'status: in-progress\n' +
    (dossier ?
      'industry: '     + (dossier.industry || '') + '\n' +
      'companySize: '  + (dossier.size     || '') + '\n' +
      'companyStage: ' + (dossier.stage    || '') + '\n' : '') +
    '---\n\n' +
    '# ' + job.title + ' - ' + job.company + '\n\n' +
    '| Field | Value |\n|---|---|\n' +
    '| Location | '   + (job.location || '') + ' |\n' +
    '| Discovered | ' + today + ' |\n' +
    '| Fit Score | '  + (job.fitScore || 0) + '/100 |\n' +
    '| Source | '     + (job.source || 'auto-search') + ' |\n' +
    (dossier ?
      '| Industry | '     + (dossier.industry || '') + ' |\n' +
