if (!OBSIDIAN_API_KEY) {
  throw new Error('OBSIDIAN_API_KEY missing from ai-config.json');
}

function vaultPath(relativePath) {
  return '/vault/' + relativePath.split('/').map(encodeURIComponent).join('/');
}

function obsidianRequest(method, relativePath, body) {
  return new Promise(function(resolve, reject) {
    var bodyBuf = body ? Buffer.from(body, 'utf8') : null;
    var opts = {
      hostname: OBSIDIAN_HOST, port: OBSIDIAN_PORT,
      path: vaultPath(relativePath), method: method,
      headers: { 'Authorization': 'Bearer ' + OBSIDIAN_API_KEY }
    };
    if (bodyBuf) {
      opts.headers['Content-Type'] = 'text/markdown';
      opts.headers['Content-Length'] = bodyBuf.length;
    }
    var req = http.request(opts, function(res) {
      var chunks = [];
      res.on('data', function(d) { chunks.push(d.toString()); });
      res.on('end',  function() { resolve({ status: res.statusCode, text: chunks.join('') }); });
    });
    req.on('error', reject);
    if (bodyBuf) req.write(bodyBuf);
    req.end();
  });
}

function mergeFrontmatter(content, additions) {
  var fmMatch = content.match(/^---\r?\n([\s\S]*?)\r?\n---(\r?\n)/);
  if (!fmMatch) {
    var block = '---\n';
    var aKeys = Object.keys(additions);
    for (var a = 0; a < aKeys.length; a++) { block += aKeys[a] + ': ' + additions[aKeys[a]] + '\n'; }
    block += '---\n\n';
    return block + content;
  }
  var fmLines  = fmMatch[1];
  var bodyPart = content.slice(fmMatch[0].length);
  var aKeys    = Object.keys(additions);
  for (var a = 0; a < aKeys.length; a++) {
    var key = aKeys[a]; var val = String(additions[key]);
    var re = new RegExp('(^|\\n)(' + key.replace(/-/g, '\\-') + '\\s*:.*)');
    if (re.test(fmLines)) {
      fmLines = fmLines.replace(re, function(m, prefix) { return prefix + key + ': ' + val; });
    } else { fmLines = fmLines + '\n' + key + ': ' + val; }
  }
  return '---\n' + fmLines + '\n---\n' + bodyPart;
}

var input   = $input.first().json;
var results = input.results || [];
var writes  = [];
var today   = new Date().toISOString().slice(0, 10);

for (var i = 0; i < results.length; i++) {
  var result = results[i];
  if (result.status !== 'success' || !result.generated || !result.paths) continue;
  try {
    if (result.clippingFile) {
      var clippingVaultPath = 'Clippings/' + result.clippingFile;
      var getRes = await obsidianRequest('GET', clippingVaultPath);
      if (getRes.status !== 200) {
        writes.push({ file: clippingVaultPath, action: 'GET', http: getRes.status, error: 'fallback to fresh' });
        var fallRes = await obsidianRequest('PUT', result.paths.obsidianJobNote, result.generated.jobNote);
        writes.push({ file: result.paths.obsidianJobNote, action: 'PUT (fallback)', http: fallRes.status });
      } else {
        var enriched = mergeFrontmatter(getRes.text, { 'match-score': result.fitScore || 100, status: 'in-progress', processed: today });
        var sections = '\n\n---\n\n## Company Research\n\n' + result.generated.research + '\n\n## Tailored Resume\n\n' + result.generated.resume + '\n\n## Cover Letter\n\n' + result.generated.coverLetter + '\n';
        var putRes = await obsidianRequest('PUT', result.paths.obsidianJobNote, enriched + sections);
        writes.push({ file: result.paths.obsidianJobNote, action: 'PUT (from clipping)', http: putRes.status });
        if (putRes.status >= 200 && putRes.status < 300) {
          var delRes = await obsidianRequest('DELETE', clippingVaultPath);
          writes.push({ file: clippingVaultPath, action: 'DELETE', http: delRes.status });
        }
      }
    } else {
      var noteRes = await obsidianRequest('PUT', result.paths.obsidianJobNote, result.generated.jobNote);
      writes.push({ file: result.paths.obsidianJobNote, action: 'PUT', http: noteRes.status });
    }
    var existRes = await obsidianRequest('GET', result.paths.obsidianCompanyResearch);
    if (existRes.status === 200) {
      var appendText = '\n\n---\n\n## Update: ' + today + ' (' + result.title + ')\n\n' + result.generated.research;
      var appendRes = await obsidianRequest('POST', result.paths.obsidianCompanyResearch, appendText);
      writes.push({ file: result.paths.obsidianCompanyResearch, action: 'POST (append)', http: appendRes.status });
    } else {
      var freshText = '---\ndate: ' + today + '\ntitle: ' + result.company + '\ncompany: ' + result.company + '\ntype: Company Research\n---\n\n# [[' + result.company + ']]\n\n' + result.generated.research + '\n\n---\n*First researched: ' + today + ' (' + result.title + ')*\n';
      var createRes = await obsidianRequest('PUT', result.paths.obsidianCompanyResearch, freshText);
      writes.push({ file: result.paths.obsidianCompanyResearch, action: 'PUT (new)', http: createRes.status });
    }
  } catch(e) { writes.push({ company: result.company, error: e.message }); }
}

var output = {};
