function ensureDir(d) {
  var parts = d.split('/');
  var cur = '';
  for (var i = 0; i < parts.length; i++) {
    if (!parts[i]) { cur = '/'; continue; }
    cur = (cur === '/' ? '/' : cur + '/') + parts[i];
    try { fs.mkdirSync(cur); } catch(e) { if (e.code !== 'EEXIST') throw e; }
  }
}

