var rawValue = $input.first().json.propertyName;
if (!rawValue) {
  return [{ json: { total: 1, succeeded: 0, skipped: 0, failed: 1,
    results: [{ status: 'error', error: 'Empty value from Redis pop' }],
    processedAt: new Date().toISOString() } }];
}

var job;
try { job = typeof rawValue === 'string' ? JSON.parse(rawValue) : rawValue; }
catch(e) {
  return [{ json: { total: 1, succeeded: 0, skipped: 0, failed: 1,
    results: [{ status: 'error', error: 'JSON parse failed: ' + e.message }],
    processedAt: new Date().toISOString() } }];
}

var log = {};
try { if (fs.existsSync(LOG_FILE)) log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8')); } catch(e) {}

if (log[job.jobId] && log[job.jobId].status === 'processed') {
  return [{ json: {
    total: 1, succeeded: 0, skipped: 1, failed: 0,
    results: [{ status: 'skipped', jobId: job.jobId, reason: 'already_processed' }],
    processedAt: new Date().toISOString() } }];
}

try {
  var result = await processJob(job);
  log[job.jobId] = {
    jobId: job.jobId, title: job.title, company: job.company,
    location: job.location || '', url: job.linkedinUrl || '',
    source: job.source || 'auto-search',
    fitScore: job.fitScore || 0,
    processedAt: new Date().toISOString(), status: 'processed',
    outputFolder: result.outputFolder
  };
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2), 'utf8');
  return [{ json: {
    total: 1, succeeded: 1, skipped: 0, failed: 0,
    results: [result],
    processedAt: new Date().toISOString() } }];
} catch(e) {
  log[job.jobId] = {
    jobId: job.jobId || 'unknown', title: job.title || 'unknown',
    company: job.company || 'unknown',
    processedAt: new Date().toISOString(), status: 'error', error: e.message
  };
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2), 'utf8');
  return [{ json: {
    total: 1, succeeded: 0, skipped: 0, failed: 1,
    results: [{ status: 'error', jobId: job.jobId, company: job.company || '', error: e.message }],
    processedAt: new Date().toISOString() } }];
}

